def solve_math_problem(base: int, exponent_base: int, exponent_power: int, modulus: int) -> int:
    """
    Calculates (base^(exponent_base^exponent_power)) % modulus using Euler's Totient Theorem.
    """
    if modulus <= 0:
        raise ValueError("Modulus must be a positive integer.")

    if modulus == 1:
        return 0

    def get_phi(n: int) -> int:
        result = n
        p = 2
        temp = n
        while p * p <= temp:
            if temp % p == 0:
                while temp % p == 0:
                    temp //= p
                result -= result // p
            p += 1
        if temp > 1:
            result -= result // temp
        return result

    phi = get_phi(modulus)

    # Euler's Totient Theorem: a^b % n = a^(b % phi(n) + phi(n)) % n 
    # if b >= phi(n).
    exponent = pow(exponent_base, exponent_power, phi)

    # We add phi to the exponent to handle the case where the exponent is large
    # and the base is not coprime to the modulus.
    return pow(base, exponent + phi, modulus)

if __name__ == "__main__":
    assert solve_math_problem(19, 17, 15, 100) == 59
    assert solve_math_problem(3, 5, 2, 10) == 3
